// Current runtime; printed art with aligned cup fill and route-blocking level generation.
// TEMPLATE_HTML_BASE64: 

/* SODA23_LAYOUT_START: shared level and cup geometry. */
function soda23LevelLayout(width,height,round,cupWidth=100,cupHeight=100){
 let state=(round*2654435761)>>>0;
 const random=()=>((state=(state*1664525+1013904223)>>>0)/4294967296);
 const edge=Math.max(cupWidth/2+22,70),span=Math.max(1,width-edge*2),sourceOnRight=random()>.5;
 const sourceFraction=(sourceOnRight?.82:.18)+(random()-.5)*.07;
 const cupFraction=(sourceOnRight?.18:.82)+(random()-.5)*.07;
 const cup={x:edge+span*cupFraction,y:height-Math.max(160,height*.22)};
 const dispenser={x:edge+span*sourceFraction,y:Math.max(60,height*.1)};
 const outletY=dispenser.y+18,mouthY=cup.y-cupHeight/2+5,travel=mouthY-outletY;
 const radius=Math.max(18,Math.min(38,travel*.105)),placed=[];
 const guide={left:30,right:width-30,top:height*.26-30,bottom:height*.26+30};
 const hitsGuide=(x,y,r)=>Math.hypot(x-Math.max(guide.left,Math.min(guide.right,x)),y-Math.max(guide.top,Math.min(guide.bottom,y)))<r+14;
 const add=(x,y,r,route=false)=>{
  if(hitsGuide(x,y,r)){
   const below=guide.bottom+r+14,above=guide.top-r-14;
   y=below<mouthY-r-16?below:above>outletY+r+8?above:below;
   if(route)x=dispenser.x+(cup.x-dispenser.x)*Math.max(0,Math.min(1,(y-outletY)/travel));
  }
  placed.push({x,y,r});
 };
 // Block the actual gravity stream, then the straight source-to-mouth route.
 add(dispenser.x+(random()-.5)*radius*.20,outletY+travel*.29,radius);
 add(dispenser.x+(cup.x-dispenser.x)*.64,outletY+travel*.64,radius*(.94+random()*.08),true);
 if(random()>.5){
  for(let attempt=0;attempt<50;attempt++){
   const r=radius*(.78+random()*.16),x=30+r+random()*Math.max(1,width-60-r*2),y=outletY+r+28+random()*Math.max(1,travel-r*2-60);
   if(!hitsGuide(x,y,r)&&placed.every(other=>Math.hypot(x-other.x,y-other.y)>r+other.r+20)&&y+r<mouthY-28){add(x,y,r);break;}
  }
 }
 return {cup,dispenser,obstacles:placed};
}
function soda23CupBodies(Matter,cup,width,height){
 const left=cup.x-width/2,top=cup.y-height/2;
 const edge=(x1,y1,x2,y2)=>Matter.Bodies.rectangle((x1+x2)/2,(y1+y2)/2,Math.hypot(x2-x1,y2-y1),4,{isStatic:true,angle:Math.atan2(y2-y1,x2-x1)});
 return [edge(left+width*.06,top+height*.05,left+width*.09,top+height*.91),edge(left+width*.94,top+height*.05,left+width*.91,top+height*.91),Matter.Bodies.rectangle(cup.x,top+height*.93,width*.84,4,{isStatic:true}),Matter.Bodies.rectangle(cup.x,top+height*.77,width*.72,height*.24,{isStatic:true,isSensor:true,label:'glassSensor'})];
}
function soda23DrawFill(ctx,cup,width,height,amount){
 const fill=Math.max(0,Math.min(1,amount));if(fill<=.002)return;
 const left=cup.x-width/2,top=cup.y-height/2,bottom=top+height*.935,surface=bottom-height*.86*fill;
 ctx.save();ctx.beginPath();
 ctx.moveTo(left+width*.08,top+height*.075);ctx.lineTo(left+width*.11,top+height*.89);
 ctx.quadraticCurveTo(left+width*.5,top+height*.98,left+width*.89,top+height*.89);
 ctx.lineTo(left+width*.92,top+height*.075);ctx.closePath();ctx.clip();
 ctx.fillStyle='#59c6b1';ctx.fillRect(left,surface,width,bottom-surface+1);
 ctx.strokeStyle='#242322';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(left,surface);ctx.lineTo(left+width,surface);ctx.stroke();ctx.restore();
}
/* SODA23_LAYOUT_END */


// Active only inside the feed reviewer. Ordinary standalone games are unchanged.
(() => {
  if (new URLSearchParams(location.search).get('feedReview') !== '1') return;
  let active=false,alive=true;
  const waiting=new Set(),contexts=new Set(),media=new Set(),streams=new Set();
  const wait=()=>alive ? new Promise((resolve,reject)=>waiting.add({resolve,reject})) : Promise.reject(new DOMException('Feed closed','AbortError'));
  if(navigator.mediaDevices?.getUserMedia){
    const native=navigator.mediaDevices.getUserMedia.bind(navigator.mediaDevices);
    navigator.mediaDevices.getUserMedia=async constraints=>{
      if(!active)await wait();if(!alive)throw new DOMException('Feed closed','AbortError');
      const stream=await native(constraints);
      if(!alive||!active){stream.getTracks().forEach(track=>track.stop());throw new DOMException('Feed inactive','AbortError');}
      streams.add(stream);return stream;
    };
  }
  for(const key of ['AudioContext','webkitAudioContext']){
    const Native=window[key];if(!Native)continue;
    window[key]=class FeedAudioContext extends Native {
      constructor(...args){super(...args);contexts.add(this);if(!active)super.suspend().catch(()=>{});}
      async resume(){if(!active)await wait();if(alive)return super.resume();}
    };
  }
  const nativePlay=HTMLMediaElement.prototype.play;
  HTMLMediaElement.prototype.play=async function(...args){media.add(this);if(!active)await wait();if(alive)return nativePlay.apply(this,args);};
  addEventListener('message',event=>{
    if(event.source!==parent||event.origin!==location.origin||event.data?.type!=='playable-active')return;
    active=alive&&event.data.active===true;
    if(active){for(const job of waiting)job.resolve();waiting.clear();for(const context of contexts)if(context.state!=='closed')context.resume().catch(()=>{});}
    else {for(const context of contexts)if(context.state!=='closed')context.suspend().catch(()=>{});for(const item of media)item.pause();for(const stream of streams)stream.getTracks().forEach(track=>track.stop());streams.clear();}
  });
  addEventListener('pagehide',()=>{alive=false;active=false;for(const job of waiting)job.reject(new DOMException('Feed closed','AbortError'));waiting.clear();for(const context of contexts)if(context.state!=='closed')context.close().catch(()=>{});for(const item of media)item.pause();for(const stream of streams)stream.getTracks().forEach(track=>track.stop());},{once:true});
})();


    (() => {
      if (window.location.protocol !== "file:" || !window.fetch) return;
      const configNode = document.getElementById("playable-inline-config");
      if (!configNode) return;
      let inlineConfig;
      try { inlineConfig = JSON.parse(configNode.textContent); } catch (_) { return; }
      const nativeFetch = window.fetch.bind(window);
      window.fetch = (input, init) => {
        const url = typeof input === "string" ? input : input && input.url;
        if (url === "./game.config.json" || url === "game.config.json") {
          return Promise.resolve(new Response(JSON.stringify(inlineConfig), {
            status: 200,
            headers: { "Content-Type": "application/json" }
          }));
        }
        return nativeFetch(input, init);
      };
    })();
  
(() => {
  const colors = {
    'var(--bg-color)': '#fdfbf7',
    'var(--color-obstacle)': '#d8eb61',
    'var(--color-soda)': '#59c6b1',
    'var(--color-primary)': '#242322'
  };
  for (const property of ['fillStyle', 'strokeStyle', 'shadowColor']) {
    const descriptor = Object.getOwnPropertyDescriptor(CanvasRenderingContext2D.prototype, property);
    if (!descriptor || !descriptor.set || !descriptor.get) continue;
    Object.defineProperty(CanvasRenderingContext2D.prototype, property, {
      configurable: true,
      enumerable: descriptor.enumerable,
      get: descriptor.get,
      set(value) {
        return descriptor.set.call(this, colors[value] || value);
      }
    });
  }

  const prepareCanvas = canvas => {
    if (!canvas || canvas.dataset.dragRepaired) return false;
    canvas.dataset.dragRepaired = 'true';
    canvas.style.touchAction = 'none';
    canvas.style.pointerEvents = 'auto';
    canvas.addEventListener('pointerdown', event => {
      if (event.isPrimary === false) return;
      event.preventDefault();
      try { canvas.setPointerCapture(event.pointerId); } catch (_) {}
    }, { capture: true, passive: false });
    const release = event => {
      try {
        if (canvas.hasPointerCapture(event.pointerId)) canvas.releasePointerCapture(event.pointerId);
      } catch (_) {}
    };
    canvas.addEventListener('pointerup', release, true);
    canvas.addEventListener('pointercancel', release, true);
    return true;
  };
  if (!prepareCanvas(document.querySelector('canvas'))) {
    const observer = new MutationObserver(() => {
      if (prepareCanvas(document.querySelector('canvas'))) observer.disconnect();
    });
    observer.observe(document.documentElement, { childList: true, subtree: true });
  }
})();

