/* Game-owned copy dismissal only: no synthetic input, progress or physics writes. */
(() => {
  'use strict';
  const script = document.currentScript;
  const actionRoot = "#root>div>canvas";
  if (!actionRoot) return;
  const arrowButtons = '';
  const ignored = '';
  const arrowKeys = false;
  const html = document.documentElement;
  const hosted = !!document.querySelector('script[src*="playable-batch/review-host.js"]') || new URLSearchParams(location.search).get('feedReview') === '1';
  let active = !hosted, used = false;
  const element = target => target && typeof target.closest === 'function' ? target : null;
  const unrelated = target => !!target.closest('input,select,textarea,a,[contenteditable="true"],[role="button"],[data-settings]');
  function dismiss() {
    if (used) return;
    used = true;
    html.setAttribute('data-guide-action-used', 'true');
  }
  function pointer(event) {
    if (!active || used || event.isTrusted === false || event.isPrimary === false || (event.button != null && event.button !== 0)) return;
    const target = element(event.target);
    if (!target || unrelated(target) || (ignored && target.closest(ignored))) return;
    const arrow = arrowButtons && target.closest(arrowButtons);
    if (target.closest('button') && !arrow) return;
    if (arrow || target.closest(actionRoot)) dismiss();
  }
  function key(event) {
    if (!arrowKeys || !active || used || event.isTrusted === false || !['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(event.key)) return;
    const target = element(event.target);
    if (target && (unrelated(target) || target.closest('input,select,textarea,button'))) return;
    dismiss();
  }
  function message(event) {
    if (!hosted || event.source !== parent || event.origin !== location.origin || event.data?.type !== 'playable-active') return;
    active = event.data.active === true;
  }
  document.addEventListener('pointerdown', pointer, {capture:true, passive:true});
  if (arrowKeys) document.addEventListener('keydown', key, {capture:true, passive:true});
  addEventListener('message', message);
  addEventListener('pagehide', () => {
    document.removeEventListener('pointerdown', pointer, true);
    document.removeEventListener('keydown', key, true);
    removeEventListener('message', message);
  }, {once:true});
})();

/* Decorative entry motion only. No game state, audio, timers or synthetic input. */
(function () {
  'use strict';
  const script = document.currentScript;
  const selector = script?.getAttribute('data-subject') || '#root canvas';
  const media = window.matchMedia?.('(prefers-reduced-motion: reduce)');
  let observer, animation, entered = false;
  function stop() { animation?.cancel(); animation = null; }
  function enter() {
    if (entered || document.hidden) return;
    const subject = document.querySelector(selector);
    if (!subject || subject.closest('[hidden], [aria-hidden="true"]')) return;
    const computed = window.getComputedStyle(subject);
    if (computed.display === 'none' || computed.visibility === 'hidden') return;
    if (subject.tagName === 'IMG' && !subject.complete) {
      subject.addEventListener('load', enter, { once: true });
      return;
    }
    entered = true;
    observer?.disconnect();
    if (media?.matches) return;
    const opacity = Number(window.getComputedStyle(subject).opacity) || 1;
    if (typeof subject.animate === 'function') {
      animation = subject.animate([{ opacity: opacity * .76 }, { opacity }], { duration: 650, easing: 'ease-out' });
      animation.onfinish = () => { animation = null; };
    }
  }
  observer = new MutationObserver(enter);
  observer.observe(document.body, { childList: true, subtree: true });
  enter();
  document.addEventListener('visibilitychange', () => {
    document.documentElement.toggleAttribute('data-feed-background', document.hidden);
    if (document.hidden) stop(); else enter();
  });
  window.addEventListener('pagehide', () => { observer.disconnect(); stop(); });
  window.addEventListener('pageshow', () => {
    if (!entered) observer.observe(document.body, { childList: true, subtree: true });
    enter();
  });
  document.addEventListener('pointerdown', stop, { capture: true, passive: true });
  media?.addEventListener?.('change', () => { if (media.matches) stop(); });
})();

/* Existing FYP palette adapter; does not draw host UI into the game. */
(()=>{
if(parent===window)return;
  // Feed palette: post a 32×12 RGBA band from the top and the bottom of the first screen. The feed
  // keeps the first valid post, so sample fast until one lands, then settle to once a second.
  const BAND = { w: 32, h: 12 };
  const post = (top, bottom) => parent.postMessage({ type: 'playable-palette', top, bottom }, '*');
  /** The game's main canvas: the largest one, if it covers a good part of the screen. */
  function mainCanvas() {
    const canvases = [...document.querySelectorAll('canvas')].filter(c => c.width && c.height);
    const source = canvases.sort((a, b) => b.clientWidth * b.clientHeight - a.clientWidth * a.clientHeight)[0];
    return source && source.clientWidth * source.clientHeight >= innerWidth * innerHeight * 0.3 ? source : null;
  }
  function sampleCanvas(source) {
    try {
      const canvas = document.createElement('canvas'); canvas.width = BAND.w; canvas.height = 48;
      const ctx = canvas.getContext('2d', { willReadFrequently: true });
      // Transparent canvas games paint their scene over a CSS background. Include that visible surface
      // rather than rejecting empty bands and leaving the generic blue/green fallback over dark games.
      for (let node = source; node && node.nodeType === 1; node = node.parentElement) {
        const color = getComputedStyle(node).backgroundColor;
        const channels = color.match(/[\d.]+/g);
        if (channels && (channels[3] === undefined || Number(channels[3]) > .5)) {
          ctx.fillStyle = color; ctx.fillRect(0,0,BAND.w,48); break;
        }
      }
      ctx.drawImage(source, 0, 0, BAND.w, 48);
      const top = Array.from(ctx.getImageData(0, 0, BAND.w, BAND.h).data);
      const bottom = Array.from(ctx.getImageData(0, 48 - BAND.h, BAND.w, BAND.h).data);
      return top.some((v, i) => i % 4 === 3 && v > 0) ? [top, bottom] : null;
    } catch { return null; }
  }
  /** DOM games: the painted background under a grid of points (images can't be read cross-origin). */
  function sampleDom() {
    const rgba = (el) => {
      for (let node = el; node && node.nodeType === 1; node = node.parentElement) {
        const match = getComputedStyle(node).backgroundColor.match(/[\d.]+/g);
        if (match && (match[3] === undefined || Number(match[3]) > 0.5)) return [+match[0], +match[1], +match[2], 255];
      }
      return null;
    };
    const band = (y0) => {
      const out = [];
      for (let row = 0; row < BAND.h; row++) for (let col = 0; col < BAND.w; col++) {
        const x = (col + 0.5) / BAND.w * innerWidth, y = y0 + (row + 0.5) / BAND.h * innerHeight * 0.25;
        out.push(...(rgba(document.elementFromPoint(x, y)) ?? rgba(document.body) ?? rgba(document.documentElement) ?? [0, 0, 0, 0]));
      }
      return out;
    };
    const top = band(0), bottom = band(innerHeight * 0.75);
    return top.some((v, i) => i % 4 === 3 && v > 0) ? [top, bottom] : null;
  }
  let sampledOnce = false;
  function sample() {
    // Converted photo templates explicitly mark their asynchronous preload. Never lock
    // the feed palette to an empty canvas or loading veil instead of the actual scene.
    if (document.documentElement.dataset.playableLoading === 'true') return;
    const land = (found) => { if (found) { sampledOnce = true; post(...found); } return !!found; };
    const source = mainCanvas();
    if (!source) { if (document.body?.childElementCount) land(sampleDom()); return; }
    // WebGL may clear after compositing; if the direct read is empty, read inside the next frame.
    if (!land(sampleCanvas(source))) requestAnimationFrame(() => land(sampleCanvas(source)));
  }
  const schedule = () => { sample(); setTimeout(schedule, sampledOnce ? 1000 : 250); };
  // Let the app paint its first screen before reading it.
  if (document.readyState === 'complete') setTimeout(schedule, 300);
  else window.addEventListener('load', () => setTimeout(schedule, 300), { once: true });
})();
